// CrowdRelay decided WHO hears from us, WHICH message, and that consent
// and cooldown allow it. This workflow renders the named template and sends
// it to one fan. It never chooses a different template, broadens the
// recipient, or sends a message CrowdRelay did not request.
const e = $json;
if (!e || e.type !== 'crowdrelay.fan_lifecycle.message_requested' || e.version !== 1) return [];
const d = e.data ?? {};
for (const key of ['action_id', 'fan_id', 'template_key']) {
  if (!d[key]) throw new Error('lifecycle request missing ' + key);
}
const fan = d.fan ?? {};
if (!fan.email || !fan.email.includes('@')) throw new Error('invalid fan.email');
return [{ json: {
  action_id: String(d.action_id),
  fan_id: String(d.fan_id),
  template_key: String(d.template_key),
  email: String(fan.email),
  display_name: fan.display_name || '',
  locale: String(fan.locale || ''),
  referral_code: fan.referral_code || null,
}}];

// Fail closed. Only `claimed` may send; `already_succeeded` is a no-op
// replay; `in_flight` and `ambiguous` require reconciliation instead of a
// second send.
const c = $input.first().json;
const plan = $('Validate lifecycle request').first().json;
if (c.status === 'already_succeeded') return [];
if (c.status !== 'claimed') throw new Error('claim not granted: ' + c.status);
return [{ json: { ...plan, claim_token: c.claim_token } }];

// Render the named template. CrowdRelay chose which message; the executor
// renders it from the supplied facts. A default branch sends the wrong
// message, which is worse than sending none — it is indistinguishable from
// working, and the fan reads a thank-you for something they did not do.
// Throw on a key you do not know.
const p = $input.first().json;
const key = p.template_key;
const name = p.display_name || '';
const hello = name ? ('Czesc ' + name) : 'Czesc';
const helloEn = name ? ('Hi ' + name) : 'Hi';
let subject, text;
if (key === 'crowdrelay.fan.welcome.v1') {
  subject = 'Witamy w VIRYA';
  text = [hello + ',', '', 'Dziekujemy za zapisanie sie do VIRYA. Od teraz koncerty, nagrody i polecenia pracuja jako jeden system.', '', '- VIRYA'].join('\n');
} else if (key === 'crowdrelay.synesthesia.follow_up.v1') {
  subject = 'Dziekujemy za Synestezje';
  text = [hello + ',', '', 'Dziekujemy za wziecie udzialu w Synestezji. Koncerty sa najblizszym krokiem — wpadnij na nastepny.', '', '- VIRYA'].join('\n');
} else if (key === 'crowdrelay.fan.reactivation.v1') {
  subject = 'Brakowalo nam Ciebie';
  text = [hello + ',', '', 'Dlugo Cie nie bylo. Najblizszy koncert jest blizej niz myslisz — wpadnij.', '', '- VIRYA'].join('\n');
} else if (key === 'crowdrelay.fan.first_ticket_thanks.v1') {
  subject = 'Dziekujemy za pierwszy bilet';
  text = [hello + ',', '', 'To Twoj pierwszy bilet na VIRYA. Dzien, w ktorym ktos kupuje pierwszy bilet, to najlepszy moment, zeby stac sie fanem.', '', 'Do zobaczenia na koncercie.', '', '- VIRYA'].join('\n');
} else if (key === 'crowdrelay.fan.returning_thanks.v1') {
  subject = 'Wracasz — i to zauwazamy';
  text = [hello + ',', '', 'Byles na wystarczajaco wielu koncertach, zeby to mialo znaczenie. Dziekujemy, ze wracasz.', '', '- VIRYA'].join('\n');
} else if (key === 'crowdrelay.fan.referral_thanks.v1') {
  subject = 'Ktos przyszedl dzieki Tobie';
  text = [hello + ',', '', 'Osoba, ktora poleciles, wlasnie dolaczyla. To jedyna petla, ktora rosnie sama — i Ty ja napędzasz.', '', '- VIRYA'].join('\n');
} else if (key === 'crowdrelay.fan.referral_invite.v1') {
  if (!p.referral_code) throw new Error('referral_invite missing fan.referral_code');
  const link = 'https://virya.music/r/' + p.referral_code;
  subject = 'Polec kogos na VIRYA';
  text = [hello + ',', '', 'Jesli znasz kogos, kto powinien byc tutaj, podziel sie swoim linkiem:', '', link, '', 'Kazdy, kto przez niego dojdzie, jest przypisany do Ciebie.', '', '- VIRYA'].join('\n');
} else {
  throw new Error('Unknown lifecycle template: ' + key);
}
return [{ json: { ...p, subject, text } }];
